import React from 'react';
import { render, screen, userEvent, waitFor } from '@testing-library/react-native';
import { Alert } from 'react-native';
import ForgotPasswordScreen from '@/app/(auth)/forgot-password';
import { supabase } from '@/lib/supabase';
import { useRouter } from 'expo-router';

describe('ForgotPasswordScreen', () => {
  const mockPush = jest.fn();
  const mockReplace = jest.fn();
  const mockBack = jest.fn();
  const mockCanGoBack = jest.fn();
  const alertSpy = jest.spyOn(Alert, 'alert');

  beforeEach(() => {
    jest.clearAllMocks();
    mockCanGoBack.mockReturnValue(true);
    (useRouter as jest.Mock).mockReturnValue({
      push: mockPush,
      replace: mockReplace,
      back: mockBack,
      canGoBack: mockCanGoBack,
    });
  });

  it('renders title, description, email input, and submit button', async () => {
    await render(<ForgotPasswordScreen />);

    expect(screen.getByText('Forgot password')).toBeTruthy();
    expect(screen.getByText(/Enter your email/)).toBeTruthy();
    expect(screen.getByPlaceholderText('Email')).toBeTruthy();
    expect(screen.getByText('Continue')).toBeTruthy();
    expect(screen.getByLabelText('Go back')).toBeTruthy();
  });

  it('navigates back when back button is pressed and canGoBack is true', async () => {
    const user = userEvent.setup();
    mockCanGoBack.mockReturnValue(true);
    await render(<ForgotPasswordScreen />);

    await user.press(screen.getByLabelText('Go back'));
    expect(mockBack).toHaveBeenCalled();
    expect(mockReplace).not.toHaveBeenCalled();
  });

  it('replaces to login when back button is pressed and canGoBack is false', async () => {
    const user = userEvent.setup();
    mockCanGoBack.mockReturnValue(false);
    await render(<ForgotPasswordScreen />);

    await user.press(screen.getByLabelText('Go back'));
    expect(mockReplace).toHaveBeenCalledWith('/(auth)/login');
    expect(mockBack).not.toHaveBeenCalled();
  });

  it('alerts error if submitted with empty email', async () => {
    const user = userEvent.setup();
    await render(<ForgotPasswordScreen />);

    await user.press(screen.getByText('Continue'));

    expect(alertSpy).toHaveBeenCalledWith(
      expect.stringMatching(/error|fail|invalid/i),
      expect.any(String),
    );
    expect(supabase.auth.resetPasswordForEmail).not.toHaveBeenCalled();
  });

  it('sends reset code and navigates to verify screen on success', async () => {
    (supabase.auth.resetPasswordForEmail as jest.Mock).mockResolvedValueOnce({
      error: null,
    });

    const user = userEvent.setup();
    await render(<ForgotPasswordScreen />);

    await user.type(screen.getByPlaceholderText('Email'), ' User@Ufl.edu ');
    await user.press(screen.getByText('Continue'));

    await waitFor(() => {
      expect(supabase.auth.resetPasswordForEmail).toHaveBeenCalledWith('user@ufl.edu');
      expect(mockPush).toHaveBeenCalledWith({
        pathname: '/(auth)/verify',
        params: { email: 'user@ufl.edu', mode: 'recovery' },
      });
    });
  });

  it('displays alert when resetPasswordForEmail returns an error', async () => {
    (supabase.auth.resetPasswordForEmail as jest.Mock).mockResolvedValueOnce({
      error: { message: 'User not found' },
    });

    const user = userEvent.setup();
    await render(<ForgotPasswordScreen />);

    await user.type(screen.getByPlaceholderText('Email'), 'ghost@ufl.edu');
    await user.press(screen.getByText('Continue'));

    await waitFor(() => {
      expect(supabase.auth.resetPasswordForEmail).toHaveBeenCalledWith('ghost@ufl.edu');
      expect(alertSpy).toHaveBeenCalledWith(
        expect.stringMatching(/error|fail|could not/i),
        expect.any(String),
      );
      expect(mockPush).not.toHaveBeenCalled();
    });
  });
});
